        int placed = 0;
        attempts = 0;
        while (!placed && attempts < 1000) {
            double x = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;
            double y = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;

            int valid = 1;
            for (int j = 0; j < i; j++) {
                double dx = x - particles[j].x;
                double dy = y - particles[j].y;
                double dist = sqrt(dx * dx + dy * dy);
                if (dist < 0.5 * CUTOFF_RADIUS) {
                    valid = 0;
                    break;
                }
            }

            if (valid) {
                particles[i].x = x;
                particles[i].y = y;
                particles[i].vx = 0.0;
                particles[i].vy = 0.0;
                particles[i].fx = 0.0;
                particles[i].fy = 0.0;
                placed = 1;
            }
            attempts++;
        }
        if (!placed) {
            particles[i].x = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;
            particles[i].y = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;
            particles[i].vx = 0.0;
            particles[i].vy = 0.0;
            particles[i].fx = 0.0;
            particles[i].fy = 0.0;
        }
    }
}

int main() {
    int n = 50;
    Particle *initial = malloc(n * sizeof(Particle));
    Particle *final = malloc(n * sizeof(Particle));

    initialize_particles(initial, n);

    // Copy to final for comparison
    memcpy(final, initial, n * sizeof(Particle));

    // Simulate a simple force to ensure movement
    for (int step = 0; step < 10; step++) {
        for (int i = 0; i < n; i++) {
            final[i].fx = 0.1 * (5.0 - final[i].x);  // Simple restoring force
            final[i].fy = 0.1 * (5.0 - final[i].y);

            final[i].vx += final[i].fx * TIME_STEP;
            final[i].vy += final[i].fy * TIME_STEP;

            final[i].x += final[i].vx * TIME_STEP;
            final[i].y += final[i].vy * TIME_STEP;
        }
    }

    // Count how many particles moved
    int moved_count = 0;
    for (int i = 0; i < n; i++) {
        double dx = final[i].x - initial[i].x;
        double dy = final[i].y - initial[i].y;
        double displacement = sqrt(dx*dx + dy*dy);
        if (displacement > 0.01) {  // Threshold for "moved"
            moved_count++;
        }
    }

    double movement_percentage = (double)moved_count / n * 100.0;
    printf("Particles that moved: %d/%d (%.1f%%)\n", moved_count, n, movement_percentage);

    free(initial);
    free(final);
    return 0;
}

